using System.Runtime.InteropServices;
namespace SmartTrainingPresenter;
public static class Office {
    public static async Task<string> Convert(string original,string profile){var folder=Path.Combine(profile,"Conversion",Guid.NewGuid().ToString());Directory.CreateDirectory(folder);var source=Path.Combine(folder,"input"+Path.GetExtension(original));File.Copy(original,source);var output=Path.Combine(folder,"slides.pdf");var converter=Environment.GetEnvironmentVariable("STP_LIBREOFFICE");if(string.IsNullOrEmpty(converter)){var guess=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"LibreOffice/program/soffice.exe");if(File.Exists(guess))converter=guess;}
        if(!string.IsNullOrEmpty(converter)){var start=new System.Diagnostics.ProcessStartInfo(converter){UseShellExecute=false,CreateNoWindow=true};foreach(var a in new[]{"-env:UserInstallation="+new Uri(Path.Combine(folder,"profile")).AbsoluteUri,"--headless","--convert-to","pdf","--outdir",folder,source})start.ArgumentList.Add(a);using var p=System.Diagnostics.Process.Start(start)??throw new IOException("تعذر بدء LibreOffice");using var cts=new CancellationTokenSource(TimeSpan.FromSeconds(180));try{await p.WaitForExitAsync(cts.Token);}catch{p.Kill(true);throw;}var converted=Path.ChangeExtension(source,".pdf");if(p.ExitCode!=0||!File.Exists(converted))throw new IOException("لم ينتج المحول PDF");File.Move(converted,output);return output;}
        var type=Type.GetTypeFromProgID("PowerPoint.Application");if(type==null)throw new InvalidOperationException("يتطلب التحويل PowerPoint أو LibreOffice محليًا. يمكنك استيراد PDF الآن.");
        // Own only this copied presentation. Never call Application.Quit or close other decks.
        dynamic? application=null,presentation=null,presentations=null;try{application=Activator.CreateInstance(type)!;presentations=application.Presentations;presentation=presentations.Open(source,-1,0,0);presentation.SaveAs(output,32);return output;}finally{if(presentation!=null){presentation.Close();Marshal.FinalReleaseComObject(presentation);}if(presentations!=null)Marshal.FinalReleaseComObject(presentations);if(application!=null)Marshal.FinalReleaseComObject(application);}
    }
}
